# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TEVBE SURESİ 60. AYETE GÖRE ZEKÂT VERİLECEK 8 SINIF</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1 - 4. Gruplar</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">1. Fakirler (Yoksullar):</text>\n  <text x="180" y="114" text-anchor="middle" font-size="11" fill="#334155">Nisap miktarı malı olmayan muhtaç kimseler</text>\n  <text x="180" y="138" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">2. Miskinler (Düşkünler):</text>\n  <text x="180" y="156" text-anchor="middle" font-size="11" fill="#334155">Geçimini sağlayacak malı ve kazancı bulunmayanlar</text>\n  <text x="180" y="180" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">3. Zekât Memurları (Âmiller):</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11" fill="#334155">Zekâtları toplamak ve dağıtmakla görevli olanlar</text>\n  <text x="180" y="220" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">4. Müellefe-i Kulûb: Kalpleri İslam\'a ısındırılacaklar</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">5 - 8. Gruplar</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">5. Köleler (Rikâb):</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#334155">Özgürlüğüne kavuşmak isteyen esir ve köleler</text>\n  <text x="520" y="138" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">6. Borçlular (Gârimîn):</text>\n  <text x="520" y="156" text-anchor="middle" font-size="11" fill="#334155">Borcunu ödeyemeyecek durumda olan kimseler</text>\n  <text x="520" y="180" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">7. Allah Yolunda Olanlar (Fî Sebîlillâh):</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11" fill="#334155">İlim, hayır ve vatan savunması için çalışanlar</text>\n  <text x="520" y="220" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">8. Yolda Kalanlar (İbnü\'s-Sebîl): Yolculukta muhtaç düşenler</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ZEKÂT KİMLERE VERİLMEZ VE İNFAK ADABI</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Zekât Verilemeyen Yakınlar (Usûl - Fürû)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• Usûl (Üst Soy): Anne, baba, dede, nine</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• Fürû (Alt Soy): Çocuklar ve torunlar</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• Eşler: Karı ve koca birbirine zekât veremez</text>\n  <text x="180" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">• Nisap miktarı malı olan zenginler</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11" fill="#166534" font-weight="bold">Dikkat: Kardeş, teyze, hala, amca, dayı gibi</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11" fill="#166534" font-weight="bold">yan soy akrabalara (fakirlerse) zekât VERİLİR!</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Zekât ve Sadaka Verme Adabı (Bakara 264-267)</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">1. Niyet: Allah rızası için (İhlasla) vermek</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">2. Gösterişten (Riya) kaçınmak, gizliliğe özen göstermek</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">3. Başa kakmamak ve gönül incitmemek</text>\n  <text x="520" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">4. Malın iyisinden ve helal olanından vermek</text>\n  <text x="520" y="204" text-anchor="middle" font-size="11" fill="#713f12">5. Önce yakın çevredeki ihtiyaç sahiplerinden</text>\n  <text x="520" y="222" text-anchor="middle" font-size="11" fill="#713f12">(yoksul akraba ve komşulardan) başlamak</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SADAKA TÜRLERİ: NORMAL SADAKA, FITIR SADAKASI VE SADAKA-İ CARİYE</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Genel Sadaka (Sünnet)</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11" fill="#334155">Zenginlik şartı aranmaz.</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11" fill="#334155">Zaman ve miktar sınırı yoktur.</text>\n  <text x="125" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Maddi ve Manevi Olabilir:</text>\n  <text x="125" y="164" text-anchor="middle" font-size="11" fill="#334155">• Tebessüm etmek</text>\n  <text x="125" y="184" text-anchor="middle" font-size="11" fill="#334155">• Yoldaki engeli kaldırmak</text>\n  <text x="125" y="204" text-anchor="middle" font-size="11" fill="#334155">• Güzel söz söylemek</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Fıtır Sadakası / Fitre (Vacip)</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11" fill="#334155">Ramazan ayında bayram</text>\n  <text x="350" y="114" text-anchor="middle" font-size="11" fill="#334155">namazından önce verilir.</text>\n  <text x="350" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">Ölçüsü:</text>\n  <text x="350" y="158" text-anchor="middle" font-size="11" fill="#334155">Bir kişinin bir günlük normal</text>\n  <text x="350" y="176" text-anchor="middle" font-size="11" fill="#334155">gıda ihtiyacı tutarıdır.</text>\n  <text x="350" y="200" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">Sağlık ve oruç şükrüdür.</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sadaka-i Cariye (Kesintisiz)</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11" fill="#334155">İnsan öldükten sonra da</text>\n  <text x="575" y="114" text-anchor="middle" font-size="11" fill="#334155">amel defterine sevap yazdırır:</text>\n  <text x="575" y="140" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">1. Hayır kurumları (Okul,</text>\n  <text x="575" y="158" text-anchor="middle" font-size="11" fill="#334155">cami, çeşme, hastane, ağaç)</text>\n  <text x="575" y="182" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">2. Faydalı ilim / eser</text>\n  <text x="575" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">3. Hayırlı evlat yetiştirmek</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
